const getSolidQueryImports = (
  prefix: 'use' | 'create',
  hasRenamedOptionsTypes: boolean,
): GeneratorDependency[] => {
  const capitalized = prefix === 'use' ? 'Use' : 'Create';
  // Solid Query renamed the plain options interfaces in v5.100.6, dropping the
  // `Solid` prefix: `SolidQueryOptions` → `QueryOptions`, `SolidInfiniteQueryOptions` →
  // `InfiniteQueryOptions`, `SolidMutationOptions` → `MutationOptions`.
  //
  // `addDependency` only emits an import when the export name appears in the
  // generated file, so listing every candidate here costs nothing for outputs
  // that do not use them.
  const queryOptionsTypeName = hasRenamedOptionsTypes
    ? 'QueryOptions'
    : 'SolidQueryOptions';
  const infiniteQueryOptionsTypeName = hasRenamedOptionsTypes
    ? 'InfiniteQueryOptions'
    : 'SolidInfiniteQueryOptions';
  const mutationOptionsTypeName = hasRenamedOptionsTypes
    ? 'MutationOptions'
    : 'SolidMutationOptions';
  return [
    {
      exports: [
        { name: `${prefix}Query`, values: true },
        { name: `${prefix}InfiniteQuery`, values: true },
        { name: `${prefix}Mutation`, values: true },
        { name: `${capitalized}QueryOptions` },
        { name: `${capitalized}InfiniteQueryOptions` },
        { name: queryOptionsTypeName },
        { name: infiniteQueryOptionsTypeName },
        { name: mutationOptionsTypeName },
        { name: 'QueryFunction' },
        { name: 'MutationFunction' },
        { name: `${capitalized}QueryResult` },
        { name: `${capitalized}InfiniteQueryResult` },
        { name: `Defined${capitalized}QueryResult` },
        { name: `Defined${capitalized}InfiniteQueryResult` },
        { name: 'DefinedInitialDataOptions' },
        { name: 'UndefinedInitialDataOptions' },
        { name: 'DefinedInitialDataInfiniteOptions' },
        { name: 'UndefinedInitialDataInfiniteOptions' },
        { name: 'QueryKey' },
        { name: 'InfiniteData' },
        { name: `${capitalized}MutationResult` },
        { name: 'DataTag' },
        { name: 'QueryClient' },
        { name: 'InvalidateOptions' },
      ],
      dependency: '@tanstack/solid-query',
    },
    {
      // `mergeProps` lets the query hook attach `queryKey` to the result
      // without mutating the read-only Solid Store (see #3347). `addDependency`
      // only emits an import when the export name appears in the generated
      // file, so mutation-only outputs never receive an unused `mergeProps`
      // import.
      exports: [{ name: 'mergeProps', values: true }],
      dependency: 'solid-js',
    },
  ];
};

/**
 * Angular Query imports.
 *
 * `QueryClient` is the one export whose kind depends on the output. Angular
 * DI resolves it by class token, so `const queryClient = inject(QueryClient)`
 * needs it at runtime — but that line is emitted only for mutation
 * invalidation. Everywhere else it is named in annotations alone
 * (`queryClient: QueryClient`, `Promise<QueryClient>` in the prefetch
 * helpers), where a value import makes the generated file trip
 * `consistent-type-imports` in the consumer's linter.
 *
 * The question is per file, not per config. With `tags-split` one tag can
 * invalidate while its sibling emits no mutation at all, and an override can
 * name an operation the spec does not have, so reading `mutationInvalidates`
 * answers a different question than the one asked. The emitted implementation
 * answers this one exactly, which is also what decides every other import in
 * the file.
 *
 * @param injectsQueryClient - Whether this file emits `inject(QueryClient)`.
 */
const getAngularQueryImports = (
  injectsQueryClient: boolean,
): GeneratorDependency[] => [
  {
    exports: [
      { name: 'injectQuery', values: true },
      { name: 'injectInfiniteQuery', values: true },
      { name: 'injectMutation', values: true },
      { name: 'InjectQueryOptions' },
      { name: 'InjectMutationOptions' },
      { name: 'CreateQueryOptions' },
      { name: 'CreateInfiniteQueryOptions' },
      { name: 'CreateMutationOptions' },
      { name: 'MutationFunctionContext' },
      { name: 'QueryFunction' },
      { name: 'MutationFunction' },
      { name: 'QueryKey' },
      { name: 'CreateQueryResult' },
      { name: 'CreateInfiniteQueryResult' },
      { name: 'InfiniteData' },
      { name: 'CreateMutationResult' },
      { name: 'DataTag' },
      { name: 'QueryClient', values: injectsQueryClient },
      { name: 'InvalidateOptions' },
      { name: 'matchQuery', values: true },
    ],
    dependency: '@tanstack/angular-query-experimental',
  },
  {
    exports: [
      { name: 'inject', values: true },
      { name: 'Signal' },
      { name: 'computed', values: true },
    ],
    dependency: '@angular/core',
  },
];

