/**
 * Query Core 5.102.0 added `queryClient.query()` / `queryClient.infiniteQuery()`
 * and deprecated `prefetchQuery` / `prefetchInfiniteQuery` in their favor.
 * Svelte Query is versioned separately and first ships that core in 6.1.39.
 */
export const isQueryV5WithQueryMethod = (
  packageJson: PackageJson | undefined,
  queryClient:
    | 'react-query'
    | 'vue-query'
    | 'svelte-query'
    | 'angular-query'
    | 'solid-query',
) => {
  const version = getPackageByQueryClient(packageJson, queryClient);

  if (!version) {
    return false;
  }

  const withoutRc = version.split('-')[0];

  return compareVersions(
    withoutRc,
    queryClient === 'svelte-query' ? '6.1.39' : '5.102.0',
  );
};

export const isSolidQueryWithUsePrefix = (
  packageJson: PackageJson | undefined,
) => {
  const version = getPackageByQueryClient(packageJson, 'solid-query');

  if (!version) {
    return false;
  }

  const withoutRc = version.split('-')[0];

  // https://github.com/TanStack/query/blob/v5.71.5/packages/solid-query/src/index.ts
  return compareVersions(withoutRc, '5.71.5');
};

/**
 * Solid Query renamed its plain options interfaces in v5.100.6, dropping the
 * `Solid` prefix:
 *   - `SolidQueryOptions` → `QueryOptions`
 *   - `SolidInfiniteQueryOptions` → `InfiniteQueryOptions`
 *   - `SolidMutationOptions` → `MutationOptions`
 *
 * The Accessor wrappers `UseQueryOptions` / `UseInfiniteQueryOptions` /
 * `UseMutationOptions` keep the same names but reference the renamed
 * interfaces internally.
 *
 * https://github.com/TanStack/query/commit/<rename-commit>
 */
export const isSolidQueryWithRenamedOptionsTypes = (
  packageJson: PackageJson | undefined,
) => {
  const version = getPackageByQueryClient(packageJson, 'solid-query');

  if (!version) {
    return false;
  }

  const withoutRc = version.split('-')[0];

  return compareVersions(withoutRc, '5.100.6');
};

export const getPackageByQueryClient = (
  packageJson: PackageJson | undefined,
  queryClient:
    | 'react-query'
    | 'vue-query'
    | 'svelte-query'
    | 'angular-query'
    | 'solid-query',
) => {
  switch (queryClient) {
    case 'react-query': {
      const pkgName = '@tanstack/react-query';
      return (
        packageJson?.resolvedVersions?.[pkgName] ??
        packageJson?.dependencies?.[pkgName] ??
        packageJson?.devDependencies?.[pkgName] ??
        packageJson?.peerDependencies?.[pkgName]
      );
    }
    case 'svelte-query': {
      const pkgName = '@tanstack/svelte-query';
      return (
        packageJson?.resolvedVersions?.[pkgName] ??
        packageJson?.dependencies?.[pkgName] ??
        packageJson?.devDependencies?.[pkgName] ??
        packageJson?.peerDependencies?.[pkgName]
      );
    }
    case 'vue-query': {
      const pkgName = '@tanstack/vue-query';
      return (
        packageJson?.resolvedVersions?.[pkgName] ??
        packageJson?.dependencies?.[pkgName] ??
        packageJson?.devDependencies?.[pkgName] ??
        packageJson?.peerDependencies?.[pkgName]
      );
    }
    case 'angular-query': {
      const pkgName = '@tanstack/angular-query-experimental';
      return (
        packageJson?.resolvedVersions?.[pkgName] ??
        packageJson?.dependencies?.[pkgName] ??
        packageJson?.devDependencies?.[pkgName] ??
        packageJson?.peerDependencies?.[pkgName]
      );
    }
    case 'solid-query': {
      const pkgName = '@tanstack/solid-query';
      return (
        packageJson?.resolvedVersions?.[pkgName] ??
        packageJson?.dependencies?.[pkgName] ??
        packageJson?.devDependencies?.[pkgName] ??
        packageJson?.peerDependencies?.[pkgName]
      );
    }
  }
};
