import {
  getRouteAsArray,
  type GetterProp,
  type GetterProps,
  GetterPropType,
  type InfiniteQueryParamLocation,
  isObject,
  isString,
  type OutputClient,
  OutputClient as OutputClientConst,
  type OutputClientFunc,
  OutputHttpClient,
  type PackageJson,
  toObjectString,
} from '@orval/core';
import { generateRequestFunction as generateFetchRequestFunction } from '@orval/fetch';

import {
  generateAxiosRequestFunction,
  getQueryArgumentsRequestType,
} from '../client';
import {
  getPackageByQueryClient,
  isQueryV5,
  isQueryV5WithDataTagError,
  isQueryV5WithInfiniteQueryOptionsError,
  isQueryV5WithMutationContextOnSuccess,
  isQueryV5WithOptionalOnMutateResult,
  isQueryV5WithQueryMethod,
  isQueryV5WithRequiredContextOnSuccess,
  isSolidQueryWithRenamedOptionsTypes,
  isSolidQueryWithUsePrefix,
  isSvelteQueryV3,
  isSvelteQueryV6,
  isVueQueryV3,
} from '../dependencies';
import type {
  FrameworkAdapter,
  FrameworkAdapterConfig,
  MutationOnSuccessContext,
} from '../framework-adapter';
import { logger } from '../logger';
import {
  getQueryOptionsDefinition,
  requiresUserSuppliedQueryOptions,
} from '../query-options';
import { getInfinitePageParamMerge, isInfinitePageParamProp } from '../utils';
import { createAngularAdapter } from './angular';
import { createReactAdapter } from './react';
import { createSolidAdapter } from './solid';
import { createSvelteAdapter } from './svelte';
import { createVueAdapter } from './vue';

/** Fill in defaults for fields that most adapters leave empty or share a common implementation. */
const withDefaults = (adapter: FrameworkAdapterConfig): FrameworkAdapter => {
  // `composed` is the fully-built adapter (defaults + overrides). Defaults that
  // need sibling fields close over it instead of using `this`, so they stay
  // correct even if a method is destructured off the adapter.
  const composed: FrameworkAdapter = {
    // --- Original defaults (false / empty string) ---
    isAngularHttp: false,
    getHttpFirstParam: () => '',
    getMutationHttpPrefix: () => '',
    getRequestUnrefStatements: () => '',
    getQueryOptionsUnrefStatements: () => '',
    wrapHookMutatorCallback: (callback, operationName) =>
      `useCallback(${callback}, [${operationName}])`,
    getQueryInvocationSuffix: () => '',

    // --- Identity / pass-through defaults ---
    transformProps: (props) => props,
    getHttpFunctionQueryProps: (qp) => qp,
    getQueryType: (type) => type,

    // --- Boolean defaults ---
    shouldDestructureNamedPathParams: () => true,
    shouldAnnotateQueryKey: () => true,
    shouldGenerateOverrideTypes: () => false,
    shouldCastQueryResult: () => true,
    shouldCastQueryOptions: () => true,

    // --- String defaults ---
    getQueryKeyPrefix: () => 'queryOptions?.queryKey ?? ',
    getQueryOptionsDefinitionPrefix: () => 'Use',

    // --- Common implementation defaults ---
    getHookPropsDefinitions: (props) => toObjectString(props, 'implementation'),

    getQueryKeyRouteString(route, shouldSplitQueryKey) {
      if (shouldSplitQueryKey) {
        return getRouteAsArray(route);
      }
      return `\`${route}\``;
    },

    generateEnabledOption(params, options) {
      if (params.length === 0) return '';
      if (!isObject(options) || !Object.hasOwn(options, 'enabled')) {
        return `enabled: ${params
          .map(({ name }) => `${name} !== null && ${name} !== undefined`)
          .join(' && ')},`;
      }
      return '';
    },

    getQueryPropertyForProp(
      prop: GetterProp,
      body: { implementation: string },
    ) {
      if (prop.type === GetterPropType.NAMED_PATH_PARAMS)
        return prop.destructured;
      return prop.type === GetterPropType.BODY
        ? body.implementation
        : prop.name;
    },

    generateRequestFunction(verbOptions, options) {
      return options.context.output.httpClient === OutputHttpClient.AXIOS
        ? generateAxiosRequestFunction(verbOptions, options, composed)
        : generateFetchRequestFunction(verbOptions, options);
    },

    getInfiniteQueryHttpProps(
      props: GetterProps,
      queryParam: string,
      _httpClient: OutputHttpClient,
      _hasMutator: boolean,
      location: InfiniteQueryParamLocation,
      isExactOptionalPropertyTypes = false,
    ) {
      return props
        .map((param) => {
          if (param.type === GetterPropType.NAMED_PATH_PARAMS)
            return param.destructured;
          return isInfinitePageParamProp(param, location)
            ? getInfinitePageParamMerge(
                param.name,
                queryParam,
                isExactOptionalPropertyTypes,
              )
            : param.name;
        })
        .join(',');
    },

    generateQueryInit({
      queryOptionsFnName,
      queryProperties,
      isRequestOptions,
    }) {
      const queryOptionsVarName = isRequestOptions ? 'queryOptions' : 'options';
      return `const ${queryOptionsVarName} = ${queryOptionsFnName}(${queryProperties}${
        queryProperties ? ',' : ''
      }${isRequestOptions ? 'options' : 'queryOptions'})`;
    },

    generateQueryInvocationArgs({
      queryOptionsVarName,
      optionalQueryClientArgument,
    }) {
      return `${queryOptionsVarName}${optionalQueryClientArgument ? ', queryClient' : ''}`;
    },

    getOptionalQueryClientArgument() {
      return composed.hasQueryV5 ? ', queryClient?: QueryClient' : '';
    },

    generateQueryArguments({
      operationName,
      definitions,
      mutationVariablesType,
      mutator,
      isRequestOptions,
      type,
      pageParamType,
      initialData,
      httpClient,
      hasInvalidation,
      useRuntimeFetcher,
      options,
    }) {
      const prefix = composed.getQueryOptionsDefinitionPrefix();
      const definition = getQueryOptionsDefinition({
        operationName,
        mutator,
        definitions,
        mutationVariablesType,
        type,
        prefix,
        hasQueryV5: composed.hasQueryV5,
        hasQueryV5WithInfiniteQueryOptionsError:
          composed.hasQueryV5WithInfiniteQueryOptionsError,
        pageParamType,
        isReturnType: false,
        initialData,
        adapter: composed,
        options,
      });

      // Options the adapter demands from the caller make the whole parameter
      // mandatory: an optional parameter could be omitted, and then the
      // `...queryOptions` spread would not carry them into the options literal.
      const requiresUserQueryOptions = requiresUserSuppliedQueryOptions(
        composed,
        type,
        options,
      );

      if (!isRequestOptions) {
        return `${type ? 'queryOptions' : 'mutationOptions'}${
          initialData === 'defined' || requiresUserQueryOptions ? '' : '?'
        }: ${definition}`;
      }

      const requestType = getQueryArgumentsRequestType(
        httpClient,
        mutator,
        useRuntimeFetcher,
      );
      const isQueryRequired =
        initialData === 'defined' || requiresUserQueryOptions;
      const skipInvalidationProp =
        !type && hasInvalidation ? 'skipInvalidation?: boolean, ' : '';
      const optionsType = `{ ${
        type ? 'query' : 'mutation'
      }${isQueryRequired ? '' : '?'}:${definition}, ${skipInvalidationProp}${requestType}}`;

      return `options${isQueryRequired ? '' : '?'}: ${optionsType}\n`;
    },

    generateMutationOnSuccess({
      operationName,
      definitions,
      mutationVariablesType,
      isRequestOptions,
      generateInvalidateCalls,
      uniqueInvalidates,
    }: MutationOnSuccessContext): string {
      const invalidateCalls = generateInvalidateCalls(uniqueInvalidates);
      const variablesType =
        mutationVariablesType ?? (definitions ? `{${definitions}}` : 'void');
      // 5.89 renamed the third parameter to `onMutateResult`; whether it is
      // nullable moved with the TanStack release, so the flag decides. See #4180.
      if (composed.hasQueryV5WithMutationContextOnSuccess) {
        if (isRequestOptions) {
          return `  const onSuccess = (data: Awaited<ReturnType<typeof ${operationName}>>, variables: ${variablesType}, onMutateResult: TContext${composed.hasQueryV5WithOptionalOnMutateResult ? ' | undefined' : ''}, context: MutationFunctionContext) => {
        if (!options?.skipInvalidation) {
    ${invalidateCalls}
        }
        mutationOptions?.onSuccess?.(data, variables, onMutateResult, context);
      };`;
        }
        return `  const onSuccess = (data: Awaited<ReturnType<typeof ${operationName}>>, variables: ${variablesType}, onMutateResult: TContext${composed.hasQueryV5WithOptionalOnMutateResult ? ' | undefined' : ''}, context: MutationFunctionContext) => {
    ${invalidateCalls}
        mutationOptions?.onSuccess?.(data, variables, onMutateResult, context);
      };`;
      } else {
        if (isRequestOptions) {
          return `  const onSuccess = (data: Awaited<ReturnType<typeof ${operationName}>>, variables: ${variablesType}, context: TContext${composed.hasQueryV5WithRequiredContextOnSuccess ? '' : ' | undefined'}) => {
        if (!options?.skipInvalidation) {
    ${invalidateCalls}
        }
        mutationOptions?.onSuccess?.(data, variables, context);
      };`;
        }
        return `  const onSuccess = (data: Awaited<ReturnType<typeof ${operationName}>>, variables: ${variablesType}, context: TContext${composed.hasQueryV5WithRequiredContextOnSuccess ? '' : ' | undefined'}) => {
    ${invalidateCalls}
        mutationOptions?.onSuccess?.(data, variables, context);
      };`;
      }
    },
    ...adapter,
  };

  return composed;
};

type QueryClientType =
  | 'react-query'
  | 'vue-query'
  | 'svelte-query'
  | 'angular-query'
  | 'solid-query';

const QUERY_CLIENT_TYPES = new Set<string>([
  'react-query',
  'vue-query',
  'svelte-query',
  'angular-query',
  'solid-query',
]);

/**
 * The client as one of the known TanStack adapters, or `undefined` for a custom
 * `OutputClientFunc`.
 *
 * `createFrameworkAdapter` casts its `outputClient` to `QueryClientType`, but a
 * custom client reaches this generator as the user's own function — naming it
 * in a message would print the function source.
 */
const asQueryClientType = (
  outputClient: OutputClient | OutputClientFunc,
): QueryClientType | undefined =>
  isString(outputClient) && QUERY_CLIENT_TYPES.has(outputClient)
    ? (outputClient as QueryClientType)
    : undefined;

/**
 * Clients already warned about, so an undetectable version is reported once per
 * run rather than once per operation.
 */
const undetectedVersionWarnings = new Set<string>();

/**
 * Warn when the installed version could not be determined and none was
 * configured.
 *
 * `isQueryV5` and friends answer `false` for an unresolvable dependency, so the
 * hooks are generated for v4. That is the right guess for a v4 project but
 * silently wrong for a v5 one — v5 needs its option types wrapped in `Partial`,
 * and without that the caller cannot omit `queryKey` (#2396). Detection only
 * fails in setups where the dependency is not visible from the resolved
 * `package.json` (a monorepo root, a catalog reference), which is exactly when
 * the user needs telling.
 */
const warnOnUndetectedQueryVersion = (
  outputClient: OutputClient | OutputClientFunc,
  packageJson: PackageJson | undefined,
  queryVersion: number | undefined,
) => {
  // A custom client has no package to name, so there is no advice to give.
  const clientType = asQueryClientType(outputClient);

  if (
    clientType === undefined ||
    queryVersion !== undefined ||
    // Angular Query is v5-only, so there is nothing to detect.
    clientType === 'angular-query' ||
    getPackageByQueryClient(packageJson, clientType) ||
    undetectedVersionWarnings.has(clientType)
  ) {
    return;
  }

  undetectedVersionWarnings.add(clientType);
  logger.warn(
    `Could not determine the installed @tanstack/${clientType} version, so hooks are generated for v4.\n` +
      `If the project is on v5, set \`override.query.version: 5\` (or point \`output.packageJson\` at the package.json that declares the dependency) — otherwise the generated option types will not accept a partial \`query\` object.`,
  );
};

/**
 * Create a FrameworkAdapter for the given output client, resolving version flags
 * from the packageJson and query config.
 */
export const createFrameworkAdapter = ({
  outputClient,
  packageJson,
  queryVersion,
}: {
  outputClient: OutputClient | OutputClientFunc;
  packageJson?: PackageJson;
  queryVersion?: number;
}): FrameworkAdapter => {
  const clientType = outputClient as QueryClientType;

  warnOnUndetectedQueryVersion(outputClient, packageJson, queryVersion);

  const _hasQueryV5 = queryVersion === 5 || isQueryV5(packageJson, clientType);

  const _hasQueryV5WithDataTagError =
    queryVersion === 5 || isQueryV5WithDataTagError(packageJson, clientType);

  const _hasQueryV5WithInfiniteQueryOptionsError =
    queryVersion === 5 ||
    isQueryV5WithInfiniteQueryOptionsError(packageJson, clientType);
  const _hasQueryV5WithMutationContextOnSuccess =
    isQueryV5WithMutationContextOnSuccess(packageJson, clientType);
  const _hasQueryV5WithOptionalOnMutateResult =
    isQueryV5WithOptionalOnMutateResult(packageJson, clientType);
  const _hasQueryV5WithRequiredContextOnSuccess =
    isQueryV5WithRequiredContextOnSuccess(packageJson, clientType);
  const _hasQueryV5WithQueryMethod = isQueryV5WithQueryMethod(
    packageJson,
    clientType,
  );

  switch (outputClient) {
    case OutputClientConst.VUE_QUERY: {
      const hasVueQueryV4 = !isVueQueryV3(packageJson) || queryVersion === 4;
      return withDefaults(
        createVueAdapter({
          hasVueQueryV4,
          hasQueryV5: _hasQueryV5,
          hasQueryV5WithDataTagError: _hasQueryV5WithDataTagError,
          hasQueryV5WithInfiniteQueryOptionsError:
            _hasQueryV5WithInfiniteQueryOptionsError,
          hasQueryV5WithMutationContextOnSuccess:
            _hasQueryV5WithMutationContextOnSuccess,
          hasQueryV5WithOptionalOnMutateResult:
            _hasQueryV5WithOptionalOnMutateResult,
          hasQueryV5WithRequiredContextOnSuccess:
            _hasQueryV5WithRequiredContextOnSuccess,
          hasQueryV5WithQueryMethod: _hasQueryV5WithQueryMethod,
        }),
      );
    }

    case OutputClientConst.SVELTE_QUERY: {
      const hasSvelteQueryV4 =
        !isSvelteQueryV3(packageJson) || queryVersion === 4;
      const _hasSvelteQueryV6 = isSvelteQueryV6(packageJson);
      return withDefaults(
        createSvelteAdapter({
          hasSvelteQueryV4,
          hasSvelteQueryV6: _hasSvelteQueryV6,
          hasQueryV5: _hasQueryV5,
          hasQueryV5WithDataTagError: _hasQueryV5WithDataTagError,
          hasQueryV5WithInfiniteQueryOptionsError:
            _hasQueryV5WithInfiniteQueryOptionsError,
          hasQueryV5WithMutationContextOnSuccess:
            _hasQueryV5WithMutationContextOnSuccess,
          hasQueryV5WithOptionalOnMutateResult:
            _hasQueryV5WithOptionalOnMutateResult,
          hasQueryV5WithRequiredContextOnSuccess:
            _hasQueryV5WithRequiredContextOnSuccess,
          hasQueryV5WithQueryMethod: _hasQueryV5WithQueryMethod,
        }),
      );
    }

    case OutputClientConst.ANGULAR_QUERY: {
      return withDefaults(
        createAngularAdapter({
          hasQueryV5: _hasQueryV5,
          hasQueryV5WithDataTagError: _hasQueryV5WithDataTagError,
          hasQueryV5WithInfiniteQueryOptionsError:
            _hasQueryV5WithInfiniteQueryOptionsError,
          hasQueryV5WithMutationContextOnSuccess:
            _hasQueryV5WithMutationContextOnSuccess,
          hasQueryV5WithOptionalOnMutateResult:
            _hasQueryV5WithOptionalOnMutateResult,
          hasQueryV5WithRequiredContextOnSuccess:
            _hasQueryV5WithRequiredContextOnSuccess,
          hasQueryV5WithQueryMethod: _hasQueryV5WithQueryMethod,
        }),
      );
    }

    case OutputClientConst.SOLID_QUERY: {
      const hasSolidQueryWithUsePrefix = isSolidQueryWithUsePrefix(packageJson);
      const hasSolidQueryWithRenamedOptionsTypes =
        isSolidQueryWithRenamedOptionsTypes(packageJson);
      return withDefaults(
        createSolidAdapter({
          hasQueryV5: _hasQueryV5,
          hasQueryV5WithDataTagError: _hasQueryV5WithDataTagError,
          hasQueryV5WithInfiniteQueryOptionsError:
            _hasQueryV5WithInfiniteQueryOptionsError,
          hasQueryV5WithMutationContextOnSuccess:
            _hasQueryV5WithMutationContextOnSuccess,
          hasQueryV5WithOptionalOnMutateResult:
            _hasQueryV5WithOptionalOnMutateResult,
          hasQueryV5WithRequiredContextOnSuccess:
            _hasQueryV5WithRequiredContextOnSuccess,
          hasQueryV5WithQueryMethod: _hasQueryV5WithQueryMethod,
          hasSolidQueryUsePrefix: hasSolidQueryWithUsePrefix,
          hasSolidQueryRenamedOptionsTypes:
            hasSolidQueryWithRenamedOptionsTypes,
        }),
      );
    }

    default: {
      // react-query is the default
      return withDefaults(
        createReactAdapter({
          hasQueryV5: _hasQueryV5,
          hasQueryV5WithDataTagError: _hasQueryV5WithDataTagError,
          hasQueryV5WithInfiniteQueryOptionsError:
            _hasQueryV5WithInfiniteQueryOptionsError,
          hasQueryV5WithMutationContextOnSuccess:
            _hasQueryV5WithMutationContextOnSuccess,
          hasQueryV5WithOptionalOnMutateResult:
            _hasQueryV5WithOptionalOnMutateResult,
          hasQueryV5WithRequiredContextOnSuccess:
            _hasQueryV5WithRequiredContextOnSuccess,
          hasQueryV5WithQueryMethod: _hasQueryV5WithQueryMethod,
        }),
      );
    }
  }
};
