/**
 * Decide whether the current operation's configuration conflicts with a
 * `mutationInvalidates` rule. The rule wires its invalidation through the
 * Mutation hook's `onSuccess`, so referencing an operation that is not
 * generated as a Mutation (either forced into a Query via per-operation
 * `useQuery: true`, or suppressed entirely) makes the rule a silent no-op.
 *
 * Returns the warning message when the conflict applies, or `undefined`
 * when the configuration is consistent.
 */
export const getMutationInvalidatesConflictWarning = ({
  operationName,
  isMutation,
  isQuery,
  mutationInvalidates,
}: {
  operationName: string;
  isMutation: boolean | undefined;
  isQuery: boolean;
  mutationInvalidates:
    | NonNullable<
        GeneratorVerbOptions['override']['query']['mutationInvalidates']
      >
    | undefined;
}): string | undefined => {
  if (isMutation) return undefined;
  if (!mutationInvalidates?.length) return undefined;

  const referencingRule = mutationInvalidates.find((rule) =>
    rule.onMutations.includes(operationName),
  );
  if (!referencingRule) return undefined;

  const generatedAs = isQuery ? 'Query hook' : 'plain function (no hook)';
  return (
    `mutationInvalidates rule references '${operationName}', but that ` +
    `operation is generated as a ${generatedAs}, not a Mutation. The ` +
    `invalidation will not fire. Either remove '${operationName}' from the ` +
    `rule's onMutations list, or configure '${operationName}' so that it ` +
    `is generated as a Mutation hook.`
  );
};

export const hasQueryParam = (
  queryParams: GetterQueryParam | undefined,
  queryParam: string | undefined,
) => {
  if (!queryParam || !queryParams) {
    return false;
  }

  return queryParams.paramNames?.includes(queryParam) ?? true;
};

/**
 * The JSON request body a `useInfiniteQueryParamLocation: 'body'` page param
 * is injected into. `propertyNames` is `undefined` when the body schema does
 * not list its properties directly (a composed `allOf`, say); the configured
 * name is then trusted, and a wrong one fails the consumer's type check on the
 * emitted `Body['name']` page param type instead of emitting a silent no-op.
 */
export interface InfiniteQueryBody {
  propertyNames?: readonly string[];
}

/**
 * When nothing is configured, infinite hooks stay allowed, just without a
 * page param. When candidates are configured but the operation declares none
 * of them, the infinite hook is suppressed so orval does not emit a useless
 * one for a non-paginated `GET`.
 *
 * With `location: 'body'` the candidates are matched against the request
 * body's properties instead, and an operation without a JSON body gets no
 * infinite hook (#4025).
 */
export const resolveInfiniteQueryParam = (
  queryParams: GetterQueryParam | undefined,
  useInfiniteQueryParam: string | string[] | undefined,
  {
    location = 'query',
    body,
  }: { location?: InfiniteQueryParamLocation; body?: InfiniteQueryBody } = {},
): { queryParam: string | undefined; infiniteHookAllowed: boolean } => {
  const candidates = (
    Array.isArray(useInfiniteQueryParam)
      ? useInfiniteQueryParam
      : [useInfiniteQueryParam]
  ).filter((name): name is string => !!name);

  if (candidates.length === 0) {
    return { queryParam: undefined, infiniteHookAllowed: true };
  }

  const queryParam =
    location === 'body'
      ? body &&
        candidates.find((name) => body.propertyNames?.includes(name) ?? true)
      : candidates.find((name) => hasQueryParam(queryParams, name));
  return { queryParam, infiniteHookAllowed: queryParam !== undefined };
};

const JSON_CONTENT_TYPE = /^application\/(?:[\w.+-]+\+)?json\b/i;

/**
 * The request body a body-located page param can be injected into: a JSON
 * body passed as an object prop. Form data, url-encoded and binary bodies are
 * serialized by the request function, so spreading the page param into them
 * is not meaningful. Property names are read best-effort from the resolved
 * body schema.
 */
export const getInfiniteQueryBody = (
  body: GetterBody,
  props: GetterProps,
  context: ContextSpec,
): InfiniteQueryBody | undefined => {
  if (
    body.isBlob ||
    body.formData ||
    body.formUrlEncoded ||
    !JSON_CONTENT_TYPE.test(body.contentType) ||
    !props.some(({ type }) => type === GetterPropType.BODY)
  ) {
    return undefined;
  }

  try {
    const { schema: requestBody } = resolveRef<OpenApiRequestBodyObject>(
      body.originalSchema,
      context,
    );
    const mediaSchema = (
      requestBody.content as
        | Record<string, { schema?: OpenApiSchemaObject } | undefined>
        | undefined
    )?.[body.contentType]?.schema;
    // A boolean schema (`true`) has no properties to read.
    if (!isObject(mediaSchema)) return {};

    const schema: object =
      '$ref' in mediaSchema
        ? resolveRef<object>(mediaSchema as OpenApiReferenceObject, context)
            .schema
        : mediaSchema;
    return 'properties' in schema && isObject(schema.properties)
      ? { propertyNames: Object.keys(schema.properties) }
      : {};
  } catch {
    return {};
  }
};

/** `TPageParam` for an infinite query, indexed off the type the param lives in. */
export const getInfinitePageParamType = ({
  queryParam,
  location,
  queryParams,
  body,
}: {
  queryParam: string | undefined;
  location: InfiniteQueryParamLocation;
  queryParams: GetterQueryParam | undefined;
  body: GetterBody;
}): string | undefined => {
  if (!queryParam) return undefined;

  if (location === 'body') {
    // A named body type is indexed directly; anything else (a union with
    // `null`, an inline literal) is wrapped so it is indexed as a whole.
    const bodyType = /^[\w$.]+$/.test(body.definition)
      ? body.definition
      : `NonNullable<${body.definition}>`;
    return `${bodyType}['${queryParam}']`;
  }

  return hasQueryParam(queryParams, queryParam) && queryParams
    ? `${queryParams.schema.name}['${queryParam}']`
    : undefined;
};

const quoteList = (values: readonly string[]) =>
  values.map((value) => `'${value}'`).join(', ');

/**
 * `resolveInfiniteQueryParam` suppresses the infinite hook when none of the
 * configured `useInfiniteQueryParam` candidates is one of the operation's
 * query parameters, so a *global* `useInfinite: true` does not emit a useless
 * infinite hook for every non-paginated `GET` (#3101). That suppression is
 * right, but it leaves no trace: an operation that opts in explicitly and
 * paginates through its request body instead — the common `POST` + filter-body
 * shape — simply gets no infinite hook and no diagnostic, which reads as orval
 * ignoring the config (#4025). Such an operation can page through its body
 * with `useInfiniteQueryParamLocation: 'body'`, which the message points at.
 *
 * Warn only for the explicit per-operation opt-in. There the user named both
 * the operation and the page param, so the message is actionable and cannot
 * become per-`GET` noise the way a warning on the global flag would.
 */
export const getSuppressedInfiniteQueryWarning = ({
  operationName,
  infiniteHookAllowed,
  operationUseInfinite,
  operationUseSuspenseInfiniteQuery,
  configuredInfiniteQueryParam,
  queryParams,
  location = 'query',
  body,
}: {
  operationName: string;
  infiniteHookAllowed: boolean;
  operationUseInfinite?: boolean;
  operationUseSuspenseInfiniteQuery?: boolean;
  configuredInfiniteQueryParam: string | string[] | undefined;
  queryParams: GetterQueryParam | undefined;
  location?: InfiniteQueryParamLocation;
  body?: InfiniteQueryBody;
}): string | undefined => {
  if (infiniteHookAllowed) return undefined;

  const requested = [
    operationUseInfinite === true ? 'useInfinite' : undefined,
    operationUseSuspenseInfiniteQuery === true
      ? 'useSuspenseInfiniteQuery'
      : undefined,
  ].filter((flag): flag is string => !!flag);
  if (requested.length === 0) return undefined;

  const candidates = (
    Array.isArray(configuredInfiniteQueryParam)
      ? configuredInfiniteQueryParam
      : [configuredInfiniteQueryParam]
  ).filter((name): name is string => !!name);

  const opening =
    `'${operationName}' sets ${quoteList(requested)}, but its ` +
    `useInfiniteQueryParam (${quoteList(candidates)})`;

  if (location === 'body') {
    if (!body) {
      return (
        `${opening} is configured with useInfiniteQueryParamLocation 'body' ` +
        `and the operation has no JSON request body to page through, so no ` +
        `infinite hook was generated.`
      );
    }

    const declared = body.propertyNames ?? [];
    const declaredText =
      declared.length > 0
        ? `only declares ${quoteList(declared)}`
        : 'declares no properties';
    return (
      `${opening} is not a property of its request body — the body ` +
      `${declaredText}, so no infinite hook was generated. Either add it to ` +
      `the body schema, or drop the infinite options for this operation.`
    );
  }

  const declared = queryParams?.paramNames ?? [];
  const declaredText =
    declared.length > 0
      ? `only declares ${quoteList(declared)}`
      : 'declares no query parameters';

  return (
    `${opening} is not one of its query parameters — the operation ` +
    `${declaredText}, so no infinite hook was generated. If the page param ` +
    `is a property of the JSON request body, set ` +
    `useInfiniteQueryParamLocation: 'body'. Otherwise declare it as a query ` +
    `parameter, or drop the infinite options for this operation.`
  );
};

const escapeRegExpMetaChars = (value: string): string =>
  value.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);

/**
 * Wraps the body parameter's type in a property string with the mutator's
 * `BodyType<T>` envelope so that user-facing Query helpers (hook signature,
 * `getXxxQueryOptions`, `getXxxQueryKey`, prefetch / invalidate / set+get
 * QueryData) match the request function's signature, which is already
 * wrapped by `client.ts`. Without this, callers that pass a plain body to
 * a non-GET Query hook (possible after #2376 routes non-GET verbs to
 * Query hooks) would hit a type mismatch against the underlying request
 * function.
 *
 * The pattern handles three prop shapes that the various
 * `toObjectString(props, ...)` callers can emit:
 *   - `name: T`                — required body
 *   - `name?: T`               — optional body
 *   - `name: undefined | T`    — `definedInitialData` overload transform
 *
 * `body.definition` is fully regex-escaped so types containing metachars
 * (e.g. `Pet[]`, `Foo | Bar`, anonymous object types) are matched
 * verbatim rather than reinterpreted as regex syntax.
 *
 * No-op when the operation has no body or the mutator does not export a
 * `BodyType<T>` wrapper, so existing GET-only Query keys are unchanged.
 */
export const wrapPropsBodyWithMutatorBodyType = ({
  propsString,
  body,
  mutator,
}: {
  propsString: string;
  body: GetterBody;
  mutator: GeneratorMutator | undefined;
}): string => {
  if (!mutator?.bodyTypeName || !body.definition) return propsString;
  const bodyDefinitionPattern = escapeRegExpMetaChars(body.definition);
  return propsString.replace(
    new RegExp(
      String.raw`(\w+\??:\s*(?:undefined\s*\|\s*)?)${bodyDefinitionPattern}`,
    ),
    `$1${mutator.bodyTypeName}<${body.definition}>`,
  );
};

/**
 * Widens a parameter signature to be optional. Skips params that already
 * carry a default value (`= ...`), since those are syntactically optional
 * and adding `?` on top would be a TypeScript error.
 */
export const makeOptionalParam = (impl: string) => {
  if (impl.includes('=')) return impl;
  return impl.replace(/^(\w+):\s*/, '$1?: ');
};

/**
 * Widens a parameter type to also accept `undefined`. Already-optional
 * (`?:`) signatures are normalized to required-with-undefined, and params
 * with a default value pass through unchanged.
 */
export const allowUndefinedParam = (impl: string) => {
  if (impl.includes('=')) return impl;
  const optional = /^(\w+)\?:\s*(.+)$/.exec(impl);
  if (optional) return `${optional[1]}: ${optional[2]} | undefined`;
  return impl.replace(/^(\w+):\s*(.+)$/, '$1: $2 | undefined');
};

/**
 * The `queryFn` entry of the emitted options literal. With `useSkipToken` a query
 * whose params are not resolved is held by `skipToken`, so a caller's own
 * `enabled` cannot replace the check and `refetch()` cannot bypass it.
 *
 * A suspense query is never held — TanStack excludes `SkipToken` from its
 * `queryFn`, which is also why it gets no generated `enabled` guard.
 */
export const getQueryFnProperty = ({
  useSkipToken,
  params,
  type,
}: {
  useSkipToken?: boolean;
  params: GetterParams;
  type: (typeof QueryType)[keyof typeof QueryType];
}) => {
  if (!useSkipToken || params.length === 0 || isSuspenseQuery(type)) {
    return 'queryFn';
  }

  const isUnresolved = params
    .map(({ name }) => `${name} === null || ${name} === undefined`)
    .join(' || ');

  return `queryFn: ${isUnresolved} ? skipToken : queryFn`;
};

/**
 * The `queryFn` entry for a literal that `queryOptions()` validates instead of
 * an `as` cast laundering it.
 *
 * TanStack declares `queryFn` on the suspense options as
 * `Exclude<…['queryFn'], SkipToken>`, an indexed access that carries
 * `| undefined`; `Partial<…>` keeps it. Spreading the caller's options over a
 * concrete `queryFn` therefore widens the property to `… | undefined`, which
 * the builder rejects under `exactOptionalPropertyTypes`. Re-asserting the
 * property after the spread drops the `undefined` while keeping the caller's
 * own `queryFn` winning, matching how `queryKey` is already resolved. See #4163.
 */
export const getBuilderQueryFnProperty = (queryFnProperty: string) => {
  const fallback = queryFnProperty.startsWith('queryFn:')
    ? `(${queryFnProperty.slice('queryFn:'.length).trim()})`
    : queryFnProperty;

  return `queryFn: queryOptions?.queryFn ?? ${fallback}`;
};

/**
 * Whether `useSkipToken` applies to this adapter. `skipToken` is exported by
 * `@tanstack/react-query` v5 only: the other v5 adapters neither import it nor
 * read their params the same way — vue unwraps refs in its `enabled` guard, for
 * one — so they keep the guard.
 */
export const resolveUseSkipToken = (
  useSkipToken: boolean | undefined,
  adapter: FrameworkAdapter,
) =>
  !!useSkipToken &&
  adapter.outputClient === OutputClient.REACT_QUERY &&
  adapter.hasQueryV5;

/**
 * Renders the `setXxxQueryData` helper as either a React hook (returns a
 * setter) or a plain function taking `queryClient`. Both shapes share the
 * same body and signature, so this collapses what would otherwise be two
 * near-identical template literals.
 *
 * A trailing `$exactMatch: boolean = true` parameter is emitted here, after
 * `propsSig`, so both shapes stay in sync; `body` is expected to read it (as
 * `{ exact: $exactMatch, ... }`). The `$` prefix keeps it from colliding with
 * a spec-derived prop name.
 */
const renderSetQueryDataHelper = ({
  doc,
  isReactQuery,
  fnName,
  propsSig,
  body,
}: {
  doc: string | undefined;
  isReactQuery: boolean;
  fnName: string;
  propsSig: string;
  body: string;
}) => {
  const docPrefix = doc ?? '';
  if (isReactQuery) {
    return `${docPrefix}export const ${fnName} = () => {
  const queryClient = useQueryClient();
  return (${propsSig}, $exactMatch: boolean = true) => {
    ${body}
  };
}\n`;
  }
  return `${docPrefix}export const ${fnName} = (queryClient: QueryClient, ${propsSig}, $exactMatch: boolean = true) => {
  ${body}
}\n`;
};

/**
 * Rewrites `name?: T` to `name: undefined | T` so a required parameter can follow
 * it (TS1016).
 *
 * Keep `undefined` first. `wrapPropsBodyWithMutatorBodyType` matches an optional
 * `undefined\s*\|\s*` prefix when it swaps in a mutator body type, and misses the
 * `T | undefined` form that `allowUndefinedParam` emits.
 */
export const widenOptionalPropsToUndefined = (
  props: GetterProps,
  field: 'definition' | 'implementation',
): GetterProps =>
  props.map((prop) => {
    const regex = new RegExp(
      String.raw`^${escapeRegExpMetaChars(prop.name)}\s*\?:`,
    );

    if (!regex.test(prop[field])) {
      return prop;
    }

    const widened = prop[field].replace(regex, `${prop.name}: undefined | `);

    return field === 'definition'
      ? { ...prop, definition: widened }
      : { ...prop, implementation: widened };
  });

/**
 * Renders the prop list shared by `getXxxQueryKey`, `setXxxQueryData` and
 * `getXxxQueryData` helpers: headers are dropped (unless `includeHeaders`
 * is set — key-mutator factories need them), path params stay required,
 * non-path params (query params, body) are passed through `widenNonPath`
 * (defaults to identity — pass `makeOptionalParam` or `allowUndefinedParam`
 * to relax the signature).
 *
 * Centralising this prevents the three call sites from drifting apart on
 * how they treat the same props.
 */
const buildKeyShapedProps = ({
  props,
  body,
  mutator,
  widenNonPath = (impl) => impl,
  includeHeaders = false,
}: {
  props: GetterProps;
  body: GetterBody;
  mutator: GeneratorMutator | undefined;
  widenNonPath?: (impl: string) => string;
  includeHeaders?: boolean;
}) =>
  wrapPropsBodyWithMutatorBodyType({
    propsString: toObjectString(
      props
        .filter((prop) => includeHeaders || prop.type !== GetterPropType.HEADER)
        .map((prop) => ({
          ...prop,
          implementation:
            prop.type === GetterPropType.PARAM ||
            prop.type === GetterPropType.NAMED_PATH_PARAMS
              ? prop.implementation
              : widenNonPath(prop.implementation),
        })),
      'implementation',
    ),
    body,
    mutator,
  });

/**
 * Computes a verb prefix segment for query keys when a non-GET operation is
 * routed to a Query hook. Without this prefix, two operations sharing a path
 * (e.g. `GET /pets` and `POST /pets`) would generate cache keys that both
 * begin with `'/pets'`, so TanStack Query would mix their cached data and
 * `invalidateQueries({ queryKey: ['/pets'] })` would match both.
 *
 * Skipped for GET (preserves existing keys) and when
 * `useOperationIdAsQueryKey` is enabled (operation IDs are already unique
 * across verb + path, so the prefix would be redundant).
 *
 * Returns the uppercased verb when a prefix should be inserted, or
 * `undefined` when no prefix is needed.
 */
export const getQueryKeyVerbPrefix = ({
  verb,
  useOperationIdAsQueryKey,
}: {
  verb: Verbs;
  useOperationIdAsQueryKey: boolean | undefined;
}): string | undefined => {
  if (useOperationIdAsQueryKey) return undefined;
  if (verb === Verbs.GET) return undefined;
  return verb.toUpperCase();
};

const getQueryFnArguments = ({
  hasQueryParam,
  hasSignal,
  hasSignalParam = false,
}: {
  hasQueryParam: boolean;
  hasSignal: boolean;
  hasSignalParam?: boolean;
}) => {
  if (!hasQueryParam && !hasSignal) {
    return '';
  }

  // Rename AbortSignal if API has a param named "signal" to avoid conflict
  const signalDestructure = hasSignalParam ? 'signal: querySignal' : 'signal';

  if (hasQueryParam) {
    if (hasSignal) {
      return `{ ${signalDestructure}, pageParam }`;
    }

    return '{ pageParam }';
  }

  return `{ ${signalDestructure} }`;
};

const generatePrefetch = ({
  usePrefetch,
  type,
  useQuery,
  useInfinite,
  operationName,
  mutator,
  doc,
  queryProps,
  dataType,
  errorType,
  queryArguments,
  queryOptionsVarName,
  queryOptionsFnName,
  queryProperties,
  isRequestOptions,
  hasQueryV5WithQueryMethod,
}: {
  operationName: string;
  mutator?: GeneratorMutator;
  type: (typeof QueryType)[keyof typeof QueryType];
  usePrefetch?: boolean;
  useQuery?: boolean;
  useInfinite?: boolean;
  doc?: string;
  queryProps: string;
  dataType: string;
  errorType: string;
  queryArguments: string;
  queryOptionsVarName: string;
  queryOptionsFnName: string;
  queryProperties: string;
  isRequestOptions: boolean;
  hasQueryV5WithQueryMethod: boolean;
}) => {
  const shouldGeneratePrefetch =
    usePrefetch &&
    (type === QueryType.QUERY ||
      type === QueryType.INFINITE ||
      (type === QueryType.SUSPENSE_QUERY && !useQuery) ||
      (type === QueryType.SUSPENSE_INFINITE && !useInfinite));

  if (!shouldGeneratePrefetch) {
    return '';
  }

  const prefetchType =
    type === QueryType.QUERY || type === QueryType.SUSPENSE_QUERY
      ? 'query'
      : 'infinite-query';
  const prefetchCall = getPrefetchCall(
    prefetchType,
    queryOptionsVarName,
    hasQueryV5WithQueryMethod,
  );

  if (mutator?.isHook) {
    const prefetchVarName = camel(
      `use-prefetch-${operationName}-${prefetchType}`,
    );
    return `${doc}export const ${prefetchVarName} = <TData = Awaited<ReturnType<${dataType}>>, TError = ${errorType}>(${queryProps} ${queryArguments}) => {
  const queryClient = useQueryClient();
  const ${queryOptionsVarName} = ${queryOptionsFnName}(${queryProperties}${
    queryProperties ? ',' : ''
  }${isRequestOptions ? 'options' : 'queryOptions'})
  return useCallback(async (): Promise<QueryClient> => {
    await ${prefetchCall}
    return queryClient;
  },[queryClient, ${queryOptionsVarName}]);
};\n`;
  } else {
    const prefetchVarName = camel(`prefetch-${operationName}-${prefetchType}`);
    return `${doc}export const ${prefetchVarName} = async <TData = Awaited<ReturnType<${dataType}>>, TError = ${errorType}>(\n queryClient: QueryClient, ${queryProps} ${queryArguments}\n  ): Promise<QueryClient> => {

  const ${queryOptionsVarName} = ${queryOptionsFnName}(${queryProperties}${
    queryProperties ? ',' : ''
  }${isRequestOptions ? 'options' : 'queryOptions'})

  await ${prefetchCall};

  return queryClient;
}\n`;
  }
};

const generateQueryImplementation = ({
  queryOption: {
    name,
    typeName: optionTypeName,
    queryParam,
    pageParamLocation = 'query',
    options,
    type,
    queryKeyFnName,
  },
  operationId,
  operationName,
  typeName,
  queryProperties,
  queryKeyProperties,
  queryParams,
  params,
  props,
  body,
  mutator,
  queryOptionsMutator,
  queryKeyMutator,
  isRequestOptions,
  response,
  httpClient,
  isExactOptionalPropertyTypes,
  hasSignal,
  useRuntimeFetcher,
  forceSuccessResponse,
  includeHttpErrorResponse,
  route,
  doc,
  deprecated,
  usePrefetch,
  useQuery,
  useInfinite,
  useInvalidate,
  useSetQueryData,
  useGetQueryData,
  useSkipToken,
  adapter,
}: {
  queryOption: {
    name: string;
    typeName: string;
    options?: object | boolean;
    type: (typeof QueryType)[keyof typeof QueryType];
    queryParam?: string;
    pageParamLocation?: InfiniteQueryParamLocation;
    queryKeyFnName: string;
  };
  isRequestOptions: boolean;
  operationId: string;
  operationName: string;
  typeName: string;
  queryProperties: string;
  queryKeyProperties: string;
  params: GetterParams;
  props: GetterProps;
  body: GetterBody;
  response: GetterResponse;
  queryParams?: GetterQueryParam;
  mutator?: GeneratorMutator;
  queryOptionsMutator?: GeneratorMutator;
  queryKeyMutator?: GeneratorMutator;
  httpClient: OutputHttpClient;
  isExactOptionalPropertyTypes: boolean;
  hasSignal: boolean;
  useRuntimeFetcher?: boolean;
  forceSuccessResponse?: boolean;
  includeHttpErrorResponse?: boolean;
  route: string;
  doc?: string;
  deprecated?: boolean;
  usePrefetch?: boolean;
  useQuery?: boolean;
  useInfinite?: boolean;
  useInvalidate?: boolean;
  useSetQueryData?: boolean;
  useGetQueryData?: boolean;
  useSkipToken?: boolean;
  adapter: FrameworkAdapter;
}) => {
  const {
    hasQueryV5,
    hasQueryV5WithDataTagError,
    hasQueryV5WithInfiniteQueryOptionsError,
  } = adapter;

  // Check if API has a param named "signal" to avoid conflict with AbortSignal
  const hasSignalParam = props.some(
    (prop: GetterProp) => prop.name === 'signal',
  );

  const requiresUserQueryOptions = requiresUserSuppliedQueryOptions(
    adapter,
    type,
    options,
  );
  const signatureProps = requiresUserQueryOptions
    ? widenOptionalPropsToUndefined(props, 'implementation')
    : props;

  // The override-type overloads end in the same mandatory `options` parameter as
  // the hook, so their props need the same widening (TS1016).
  const queryPropDefinitions = wrapPropsBodyWithMutatorBodyType({
    propsString: toObjectString(
      requiresUserQueryOptions
        ? widenOptionalPropsToUndefined(props, 'definition')
        : props,
      'definition',
    ),
    body,
    mutator,
  });
  const definedInitialDataQueryPropsDefinitions =
    wrapPropsBodyWithMutatorBodyType({
      propsString: toObjectString(
        widenOptionalPropsToUndefined(props, 'definition'),
        'definition',
      ),
      body,
      mutator,
    });

  const queryProps = wrapPropsBodyWithMutatorBodyType({
    propsString: toObjectString(props, 'implementation'),
    body,
    mutator,
  });

  // Only the signatures that end in a mandatory `options` parameter may use the
  // widened props; a required parameter cannot follow an optional one (TS1016).
  // The invalidate helper's trailing `options?` is optional, so widening its
  // props would add a required argument for no reason.
  const queryPropsBeforeRequiredOptions = requiresUserQueryOptions
    ? wrapPropsBodyWithMutatorBodyType({
        propsString: toObjectString(signatureProps, 'implementation'),
        body,
        mutator,
      })
    : queryProps;

  const infiniteQueryParamType =
    getInfinitePageParamType({
      queryParam,
      location: pageParamLocation,
      queryParams,
      body,
    }) ?? '';
  const hasInfiniteQueryParam = !!infiniteQueryParamType;

  const httpFunctionProps = queryParam
    ? adapter.getInfiniteQueryHttpProps(
        props,
        queryParam,
        httpClient,
        !!mutator,
        pageParamLocation,
        isExactOptionalPropertyTypes,
      )
    : adapter.getHttpFunctionQueryProps(queryProperties, httpClient, !!mutator);

  const definedInitialDataReturnType = adapter.getQueryReturnType({
    type,
    isMutatorHook: mutator?.isHook,
    operationName,
    hasQueryV5,
    hasQueryV5WithDataTagError,
    isInitialDataDefined: true,
  });
  const returnType = adapter.getQueryReturnType({
    type,
    isMutatorHook: mutator?.isHook,
    operationName,
    hasQueryV5,
    hasQueryV5WithDataTagError,
  });

  const errorType = getQueryErrorType(
    typeName,
    response,
    httpClient,
    mutator,
    forceSuccessResponse,
    includeHttpErrorResponse,
  );

  const dataType = mutator?.isHook
    ? `ReturnType<typeof use${pascal(operationName)}Hook>`
    : `typeof ${operationName}`;

  const definedInitialDataQueryArguments = adapter.generateQueryArguments({
    operationName,
    mutator,
    definitions: '',
    isRequestOptions,
    type,
    pageParamType: infiniteQueryParamType,
    initialData: 'defined',
    httpClient,
    useRuntimeFetcher,
    options,
  });
  const undefinedInitialDataQueryArguments = adapter.generateQueryArguments({
    operationName,
    definitions: '',
    mutator,
    isRequestOptions,
    type,
    pageParamType: infiniteQueryParamType,
    initialData: 'undefined',
    httpClient,
    useRuntimeFetcher,
    options,
  });
  const queryArguments = adapter.generateQueryArguments({
    operationName,
    definitions: '',
    mutator,
    isRequestOptions,
    type,
    pageParamType: infiniteQueryParamType,
    httpClient,
    useRuntimeFetcher,
    options,
  });

  // Separate arguments for getQueryOptions function (includes http: HttpClient param for Angular)
  const queryArgumentsForOptions = adapter.generateQueryArguments({
    operationName,
    definitions: '',
    mutator,
    isRequestOptions,
    type,
    pageParamType: infiniteQueryParamType,
    httpClient,
    forQueryOptions: true,
    useRuntimeFetcher,
    options,
  });

  const queryOptions = getQueryOptions({
    isRequestOptions,
    isExactOptionalPropertyTypes,
    mutator,
    hasSignal,
    httpClient,
    hasSignalParam,
    useRuntimeFetcher,
  });

  const hookOptions = getHookOptions({
    isRequestOptions,
    httpClient,
    mutator,
    useRuntimeFetcher,
  });

  const queryFnArguments = getQueryFnArguments({
    hasQueryParam:
      !!queryParam &&
      props.some(
        ({ type }) =>
          type ===
          (pageParamLocation === 'body'
            ? GetterPropType.BODY
            : GetterPropType.QUERY_PARAM),
      ),
    hasSignal,
    hasSignalParam,
  });

  const queryOptionFnReturnType = getQueryOptionsDefinition({
    operationName,
    mutator,
    definitions: '',
    type,
    prefix: adapter.getQueryOptionsDefinitionPrefix(),
    hasQueryV5,
    hasQueryV5WithInfiniteQueryOptionsError,
    pageParamType: infiniteQueryParamType,
    isReturnType: true,
    adapter,
  });

  const queryOptionsImp = generateQueryOptions({
    params,
    options,
    type,
    adapter,
    useSkipToken,
  });

  const queryFnProperty = getQueryFnProperty({ useSkipToken, params, type });

  // Validate suspense options with TanStack's `queryOptions()` builder while
  // retaining the public suspense type and error inference. v5-only; a
  // custom `override.query.queryOptions` mutator is left unwrapped because its
  // generic typing may lose inference through the builder. See #1788.
  const useQueryOptionsHelper =
    hasQueryV5 &&
    !queryOptionsMutator &&
    (adapter.getQueryOptionsHelperTypes?.() ?? []).includes(type);

  // The builder type-checks the literal, so `queryFn` has to trail the caller
  // spread that would otherwise widen it — see `getBuilderQueryFnProperty`.
  // `override.query.options: false` drops the spread, and then the plain
  // property is both correct and what the caller asked for.
  const builderQueryOptionsLiteral = queryOptionsImp.includes('...queryOptions')
    ? `queryOptionsBuilder({ queryKey, ${queryOptionsImp}, ${getBuilderQueryFnProperty(queryFnProperty)}})`
    : `queryOptionsBuilder({ queryKey, ${queryFnProperty}, ${queryOptionsImp}})`;

  const queryOptionsFnName = camel(
    shouldUseOptionsHook({
      optionsMutator: queryOptionsMutator,
      queryKeyMutator,
      mutator,
    })
      ? `use-${name}-queryOptions`
      : `get-${name}-queryOptions`,
  );

  const queryOptionsVarName = isRequestOptions ? 'queryOptions' : 'options';

  const hasParamReservedWord = props.some(
    (prop: GetterProp) => prop.name === 'query',
  );
  const queryResultVarName = hasParamReservedWord ? '_query' : 'query';

  const infiniteParam = infiniteQueryParamType
    ? `, ${infiniteQueryParamType}`
    : '';
  const TData =
    hasQueryV5 &&
    (type === QueryType.INFINITE || type === QueryType.SUSPENSE_INFINITE)
      ? `InfiniteData<Awaited<ReturnType<${dataType}>>${infiniteParam}>`
      : `Awaited<ReturnType<${dataType}>>`;

  // For Angular, add http: HttpClient as FIRST param (required, before optional params)
  // This avoids TS1016 "required param cannot follow optional param"
  const httpFirstParam = adapter.getHttpFirstParam(mutator);

  const queryOptionsFn = `export const ${queryOptionsFnName} = <TData = ${TData}, TError = ${errorType}>(${httpFirstParam}${queryPropsBeforeRequiredOptions} ${queryArgumentsForOptions}) => {

${hookOptions}

  const queryKey =  ${
    queryKeyMutator
      ? `${queryKeyMutator.name}({ ${queryProperties} }${
          queryKeyMutator.hasSecondArg
            ? `, { url: \`${route}\`, queryOptions }`
            : ''
        });`
      : `${adapter.getQueryKeyPrefix()}${queryKeyFnName}(${queryKeyProperties});`
  }

  ${
    mutator?.isHook
      ? `const ${operationName} =  use${pascal(operationName)}Hook();`
      : ''
  }

    const queryFn: QueryFunction<Awaited<ReturnType<${
      mutator?.isHook
        ? `ReturnType<typeof use${pascal(operationName)}Hook>`
        : `typeof ${operationName}`
    }>>${
      hasQueryV5 && hasInfiniteQueryParam
        ? `, QueryKey, ${infiniteQueryParamType}`
        : // Without an explicit page param the queryFn's TPageParam defaults to
          // `never` while the options interface defaults it to `unknown`. An
          // adapter that casts the options literal launders that mismatch; one
          // that does not needs the two spelled out so they agree.
          hasQueryV5 &&
            isInfiniteQuery(type) &&
            adapter.shouldCastQueryOptions?.() === false
          ? `, QueryKey, unknown`
          : ''
    }> = (${queryFnArguments}) => ${operationName}(${httpFunctionProps}${
      httpFunctionProps ? ', ' : ''
    }${queryOptions});

      ${adapter.getQueryOptionsUnrefStatements(props)}

      ${
        queryOptionsMutator
          ? // Pass the same options object the non-mutator branch returns so
            // generated guards (e.g. the `enabled` clause for nullish path
            // params) reach the mutator instead of being dropped. See #1522.
            // The third arg additionally carries operation identity (matching
            // mutationOptions per #1974) so mutators can branch on the source
            // operation. See #3153.
            `const customOptions = ${
              queryOptionsMutator.name
            }({ queryKey, ${queryFnProperty}, ${queryOptionsImp}}${
              queryOptionsMutator.hasSecondArg ? `, { ${queryProperties} }` : ''
            }${
              queryOptionsMutator.hasThirdArg
                ? `, { url: \`${route}\`, ${getOperationMetaLiteral(
                    operationId,
                    operationName,
                  )} }`
                : ''
            });`
          : ''
      }

   return  ${
     useQueryOptionsHelper
       ? // Validate the literal with the builder, then preserve the existing
         // suspense surface and selected-data key brand. The inference-only
         // member carries TError through useSuspenseQueries without allowing
         // callers to configure or invoke throwOnError.
         builderQueryOptionsLiteral
       : queryOptionsMutator
         ? 'customOptions'
         : `{ queryKey, ${queryFnProperty}, ${queryOptionsImp}}`
   }${
     adapter.shouldCastQueryOptions?.() === false
       ? ''
       : ` as ${queryOptionFnReturnType} ${
           adapter.shouldAnnotateQueryKey()
             ? `& { queryKey: ${hasQueryV5 ? `DataTag<QueryKey, TData${hasQueryV5WithDataTagError ? ', TError' : ''}>` : 'QueryKey'} }`
             : ''
         }${
           useQueryOptionsHelper
             ? ` & { throwOnError?: ((this: never, error: TError) => boolean) & { readonly __inferenceOnly: never } }`
             : ''
         }`
   }
}`;
  const operationPrefix = adapter.hookPrefix;
  const optionalQueryClientArgument = adapter.getOptionalQueryClientArgument();

  const queryHookName = camel(`${operationPrefix}-${name}`);
  const invalidateDoc = jsDoc({
    summary: `Invalidates the {@link ${queryHookName}} query`,
    deprecated,
  });

  const overrideTypes = `
export function ${queryHookName}<TData = ${TData}, TError = ${errorType}>(\n ${definedInitialDataQueryPropsDefinitions} ${definedInitialDataQueryArguments} ${optionalQueryClientArgument}\n  ): ${definedInitialDataReturnType}
export function ${queryHookName}<TData = ${TData}, TError = ${errorType}>(\n ${queryPropDefinitions} ${undefinedInitialDataQueryArguments} ${optionalQueryClientArgument}\n  ): ${returnType}
export function ${queryHookName}<TData = ${TData}, TError = ${errorType}>(\n ${queryPropDefinitions} ${queryArguments} ${optionalQueryClientArgument}\n  ): ${returnType}`;

  const prefetchContext = {
    usePrefetch,
    type,
    useQuery,
    useInfinite,
    operationName,
    mutator,
    queryProps: queryPropsBeforeRequiredOptions,
    dataType,
    errorType,
    queryArguments: queryArgumentsForOptions,
    queryOptionsVarName,
    queryOptionsFnName,
    queryProperties,
    isRequestOptions,
    doc,
    hasQueryV5WithQueryMethod: adapter.hasQueryV5WithQueryMethod,
  };

  const prefetch = adapter.generatePrefetch
    ? adapter.generatePrefetch(prefetchContext)
    : generatePrefetch(prefetchContext);

  const isPrimaryQueryType =
    type === QueryType.QUERY ||
    type === QueryType.INFINITE ||
    (type === QueryType.SUSPENSE_QUERY && !useQuery) ||
    (type === QueryType.SUSPENSE_INFINITE && !useInfinite);

  const buildBaseQueryKeyExpr = () =>
    queryKeyMutator
      ? `${queryKeyMutator.name}({ ${queryProperties} }${
          queryKeyMutator.hasSecondArg ? `, { url: \`${route}\` }` : ''
        })`
      : `${queryKeyFnName}(${queryKeyProperties})`;

  // queryOptions mutator may augment the queryKey (e.g. tenant prefix).
  // Route invalidate / set / get helpers through the mutator so the key
  // matches what the query hook actually wrote into the cache. Hook-shaped
  // mutators are skipped here because none of these helpers can legally
  // call a hook at the right time — set/get helpers stop being emitted
  // entirely in that case (see `hasHookMutator` below), and invalidate
  // falls back to the unmutated base key for backwards compatibility.
  const applyQueryOptionsMutator = (baseExpr: string) =>
    queryOptionsMutator && !queryOptionsMutator.isHook
      ? `${queryOptionsMutator.name}({ queryKey: ${baseExpr} }${
          queryOptionsMutator.hasSecondArg ? `, { ${queryProperties} }` : ''
        }${
          queryOptionsMutator.hasThirdArg
            ? `, { url: \`${route}\`, ${getOperationMetaLiteral(
                operationId,
                operationName,
              )} }`
            : ''
        }).queryKey`
      : baseExpr;

  // Hook-shaped queryOptions mutators rewrite the queryKey at hook-call
  // time, but the set/get helpers cannot call a hook to recover that key.
  // Emitting them would silently target a different cache slot than the
  // query hook actually wrote into, so we skip generation in that case and
  // surface a warning to the user. Invalidate is left alone for backwards
  // compatibility — it has shipped with the same gap and changing its
  // contract is out of scope here.
  const hasHookMutator = !!queryOptionsMutator?.isHook;
  if (hasHookMutator && (useSetQueryData || useGetQueryData)) {
    logger.warn(
      `'${name}' has a hook-based queryOptions mutator, so the requested set/get-query-data helpers were skipped to avoid a cache-key mismatch with the query hook.`,
    );
  }

  const shouldGenerateInvalidate = useInvalidate && isPrimaryQueryType;
  const invalidateFnName = camel(`invalidate-${name}`);
  const invalidateQueryKeyExpr = applyQueryOptionsMutator(
    buildBaseQueryKeyExpr(),
  );

  const shouldGenerateSetQueryData =
    useSetQueryData && isPrimaryQueryType && !hasHookMutator;
  const isReactQuery = adapter.outputClient === OutputClient.REACT_QUERY;
  const setQueryDataFnName = isReactQuery
    ? camel(`use-set-${name}-query-data`)
    : camel(`set-${name}-query-data`);
  // Route the set-query-data key through the same mutator as invalidate so
  // that any user-applied prefix (e.g. tenant) is honoured. Without this,
  // `setQueriesData` and `invalidateQueries` would target different keys.
  const setQueryDataKeyExpr = applyQueryOptionsMutator(buildBaseQueryKeyExpr());
  // `setQueriesData` can match by query-key prefix, so non-path props (query
  // params, body) are widened to `T | undefined` — passing `undefined`
  // together with `$exactMatch: false` updates every cached entry sharing the
  // path prefix, matching what `getXxxQueryKey()` already allows. Note the
  // helper defaults to `$exactMatch: true`, so `undefined` on its own matches
  // only the entry cached without that argument. `T | undefined` is used
  // instead of `?:` because the `updater` parameter follows and TS1016
  // forbids a required parameter after an optional one.
  const setQueryDataProps = buildKeyShapedProps({
    props,
    body,
    mutator,
    widenNonPath: allowUndefinedParam,
  });

  const shouldGenerateGetQueryData =
    useGetQueryData && isPrimaryQueryType && !hasHookMutator;
  const getQueryDataFnName = isReactQuery
    ? camel(`use-get-${name}-query-data`)
    : camel(`get-${name}-query-data`);
  // `getQueryData` reads a single cache entry — keep every prop required and
  // reuse `setQueryDataKeyExpr` so read and write target the same slot.
  const getQueryDataProps = buildKeyShapedProps({ props, body, mutator });

  // Generate query init (e.g. const queryOptions = fn(...) or const http = inject(HttpClient))
  const queryInit = adapter.generateQueryInit({
    queryOptionsFnName,
    queryProperties,
    isRequestOptions,
    mutator,
  });

  // Generate query hook invocation arguments
  const queryInvocationArgs = adapter.generateQueryInvocationArgs({
    props,
    queryOptionsFnName,
    queryProperties,
    isRequestOptions,
    mutator,
    operationPrefix,
    type,
    queryOptionsVarName,
    optionalQueryClientArgument,
  });

  const queryInvocationSuffix = adapter.getQueryInvocationSuffix();

  return `
${queryOptionsFn}

export type ${pascal(
    optionTypeName,
  )}QueryResult = NonNullable<Awaited<ReturnType<${dataType}>>>
export type ${pascal(optionTypeName)}QueryError = ${errorType}

${adapter.shouldGenerateOverrideTypes() ? overrideTypes : ''}
${doc}
export function ${queryHookName}<TData = ${TData}, TError = ${errorType}>(\n ${wrapPropsBodyWithMutatorBodyType(
    {
      propsString: adapter.getHookPropsDefinitions(signatureProps),
      body,
      mutator,
    },
  )} ${queryArguments} ${optionalQueryClientArgument} \n ): ${returnType} {

  ${queryInit}

  const ${queryResultVarName} = ${camel(
    `${operationPrefix}-${adapter.getQueryType(type)}`,
  )}(${queryInvocationArgs}${queryInvocationSuffix})${adapter.shouldCastQueryResult?.() === false ? '' : ` as ${returnType}`};

  ${adapter.getQueryReturnStatement({
    hasQueryV5,
    hasQueryV5WithDataTagError,
    queryResultVarName,
    queryOptionsVarName,
  })}
}\n
${prefetch}
${
  shouldGenerateInvalidate
    ? `${invalidateDoc}export const ${invalidateFnName} = async (\n queryClient: QueryClient, ${queryProps} options?: InvalidateOptions\n  ): Promise<QueryClient> => {

  await queryClient.invalidateQueries({ queryKey: ${invalidateQueryKeyExpr} }, options);

  return queryClient;
}\n`
    : ''
}
${
  shouldGenerateSetQueryData
    ? renderSetQueryDataHelper({
        doc,
        isReactQuery,
        fnName: setQueryDataFnName,
        propsSig: `${setQueryDataProps}updater: ${TData} | undefined | ((old: ${TData} | undefined) => ${TData} | undefined)`,
        body: `queryClient.setQueriesData<${TData}>({ exact: $exactMatch, queryKey: ${setQueryDataKeyExpr} }, updater);`,
      })
    : ''
}
${
  shouldGenerateGetQueryData
    ? isReactQuery
      ? `${doc}export const ${getQueryDataFnName} = () => {
  const queryClient = useQueryClient();
  return (${getQueryDataProps}) =>
    queryClient.getQueryData<${TData}>(${setQueryDataKeyExpr});
}\n`
      : `${doc}export const ${getQueryDataFnName} = (queryClient: QueryClient, ${getQueryDataProps}) =>
  queryClient.getQueryData<${TData}>(${setQueryDataKeyExpr});\n`
    : ''
}
`;
};

export const generateQueryHook = async (
  verbOptions: GeneratorVerbOptions,
  options: GeneratorOptions,
  outputClient: OutputClient | OutputClientFunc,
  adapter?: FrameworkAdapter,
) => {
  if (!adapter) {
    throw new Error('FrameworkAdapter is required for generateQueryHook');
  }

  const {
    queryParams,
    operationName,
    typeName,
    body,
    props: _props,
    verb,
    params,
    override,
    mutator,
    response,
    operationId,
    summary,
    deprecated,
  } = verbOptions;
  const {
    route,
    override: { operations },
    context,
    output,
  } = options;

  // Use adapter to transform props (Vue wraps with MaybeRef)
  const props = adapter.transformProps(_props);

  const query = override.query;
  const isRequestOptions = override.requestOptions !== false;
  const operationQueryOptions = operations[operationId]?.query;
  const isExactOptionalPropertyTypes =
    !!context.output.tsconfig?.compilerOptions?.exactOptionalPropertyTypes;

  const httpClient = context.output.httpClient;
  const doc = jsDoc({ summary, deprecated });

  let implementation = '';
  let mutators: GeneratorMutator[] | undefined;

  // Precedence: per-operation override > global > per-verb default.
  // `?? false` lets per-op `false` actually disable a globally enabled
  // hook (the previous `[…].some(Boolean)` masked op-level false).
  const effectiveUseQuery =
    operationQueryOptions?.useQuery ??
    override.query.useQuery ??
    verb === Verbs.GET;
  const effectiveUseMutation =
    operationQueryOptions?.useMutation ??
    override.query.useMutation ??
    verb !== Verbs.GET;

  // Suspense / Infinite have no per-verb default; global is GET-only,
  // per-op overrides bypass that restriction in either direction.
  const globalSuspenseOrInfiniteOnlyForGet = (
    flag: boolean | undefined,
  ): boolean => flag === true && verb === Verbs.GET;
  const effectiveUseSuspenseQuery =
    operationQueryOptions?.useSuspenseQuery ??
    globalSuspenseOrInfiniteOnlyForGet(override.query.useSuspenseQuery);
  // Read the per-operation value directly instead of trusting the merged
  // `query`: `mergeDeep` concatenates arrays, so an op-level candidate array
  // would be appended after the global one and lose first-match resolution.
  const configuredInfiniteQueryParam =
    operationQueryOptions?.useInfiniteQueryParam ?? query.useInfiniteQueryParam;
  const infiniteQueryParamLocation =
    operationQueryOptions?.useInfiniteQueryParamLocation ??
    query.useInfiniteQueryParamLocation ??
    'query';
  const infiniteQueryBody =
    infiniteQueryParamLocation === 'body'
      ? getInfiniteQueryBody(body, props, context)
      : undefined;
  const { queryParam: infiniteQueryParam, infiniteHookAllowed } =
    resolveInfiniteQueryParam(queryParams, configuredInfiniteQueryParam, {
      location: infiniteQueryParamLocation,
      body: infiniteQueryBody,
    });
  const effectiveUseInfinite =
    (operationQueryOptions?.useInfinite ??
      globalSuspenseOrInfiniteOnlyForGet(override.query.useInfinite)) &&
    infiniteHookAllowed;
  const effectiveUseSuspenseInfiniteQuery =
    (operationQueryOptions?.useSuspenseInfiniteQuery ??
      globalSuspenseOrInfiniteOnlyForGet(
        override.query.useSuspenseInfiniteQuery,
      )) &&
    infiniteHookAllowed;

  const suppressedInfiniteWarning = getSuppressedInfiniteQueryWarning({
    operationName,
    infiniteHookAllowed,
    operationUseInfinite: operationQueryOptions?.useInfinite,
    operationUseSuspenseInfiniteQuery:
      operationQueryOptions?.useSuspenseInfiniteQuery,
    configuredInfiniteQueryParam,
    queryParams,
    location: infiniteQueryParamLocation,
    body: infiniteQueryBody,
  });
  if (suppressedInfiniteWarning) {
    logger.warn(suppressedInfiniteWarning);
  }

  let isQuery =
    effectiveUseQuery ||
    effectiveUseSuspenseQuery ||
    effectiveUseInfinite ||
    effectiveUseSuspenseInfiniteQuery;

  // No verb gate here: `effectiveUseMutation` already encodes the
  // per-verb default (`verb !== Verbs.GET`), so an explicit
  // `useMutation: true` — global or per-operation — must be honoured for
  // GET operations too, mirroring how `isQuery` honours `useQuery: true`
  // for non-GET verbs (#3358).
  let isMutation = effectiveUseMutation;

  // If both query and mutation are true for a non-GET operation, prioritize query
  if (verb !== Verbs.GET && isQuery) {
    isMutation = false;
  }

  // If both query and mutation are true for a GET operation, prioritize mutation
  if (verb === Verbs.GET && isMutation) {
    isQuery = false;
  }

  const useSkipToken = resolveUseSkipToken(
    override.query.useSkipToken,
    adapter,
  );

  // Warn when an operation referenced by a `mutationInvalidates` rule's
  // `onMutations` list is generated as a Query (or no hook at all). The rule
  // is wired up in mutation-generator and only fires for Mutation hooks, so
  // referencing a Query-emitted operation is a silent no-op — surface that
  // misconfiguration explicitly.
  const conflictWarning = getMutationInvalidatesConflictWarning({
    operationName,
    isMutation,
    isQuery,
    mutationInvalidates: override.query.mutationInvalidates,
  });
  if (conflictWarning) {
    logger.warn(conflictWarning);
  }

  if (isQuery) {
    const queryKeyMutator = query.queryKey
      ? await generateMutator({
          output,
          mutator: query.queryKey,
          name: `${operationName}QueryKey`,
          workspace: context.workspace,
          tsconfig: context.output.tsconfig,
        })
      : undefined;

    const queryOptionsMutator = query.queryOptions
      ? await generateMutator({
          output,
          mutator: query.queryOptions,
          name: `${operationName}QueryOptions`,
          workspace: context.workspace,
          tsconfig: context.output.tsconfig,
        })
      : undefined;

    // Use adapter to determine how to map props to query properties
    const queryProperties = props
      .map((param) => {
        return adapter.getQueryPropertyForProp(param, body);
      })
      .join(',');

    const queryKeyProperties = props
      .filter((prop) => prop.type !== GetterPropType.HEADER)
      .map((param) => {
        return adapter.getQueryPropertyForProp(param, body);
      })
      .join(',');

    const queries = [
      ...(effectiveUseInfinite
        ? [
            {
              name: camel(`${operationName}-infinite`),
              typeName: camel(`${typeName}-infinite`),
              options: query.options,
              type: QueryType.INFINITE,
              queryParam: infiniteQueryParam,
              pageParamLocation: infiniteQueryParamLocation,
              queryKeyFnName: camel(`get-${operationName}-infinite-query-key`),
            },
          ]
        : []),
      ...(effectiveUseQuery
        ? [
            {
              name: operationName,
              typeName,
              options: query.options,
              type: QueryType.QUERY,
              queryKeyFnName: camel(`get-${operationName}-query-key`),
            },
          ]
        : []),
      ...(effectiveUseSuspenseQuery
        ? [
            {
              name: camel(`${operationName}-suspense`),
              typeName: camel(`${typeName}-suspense`),
              options: query.options,
              type: QueryType.SUSPENSE_QUERY,
              queryKeyFnName: camel(`get-${operationName}-query-key`),
            },
          ]
        : []),
      ...(effectiveUseSuspenseInfiniteQuery
        ? [
            {
              name: camel(`${operationName}-suspense-infinite`),
              typeName: camel(`${typeName}-suspense-infinite`),
              options: query.options,
              type: QueryType.SUSPENSE_INFINITE,
              queryParam: infiniteQueryParam,
              pageParamLocation: infiniteQueryParamLocation,
              queryKeyFnName: camel(`get-${operationName}-infinite-query-key`),
            },
          ]
        : []),
    ];

    const uniqueQueryOptionsByKeys = queries.filter(
      (obj, index, self) =>
        index ===
        self.findIndex((t) => t.queryKeyFnName === obj.queryKeyFnName),
    );

    let queryKeyFns = '';

    if (!queryKeyMutator) {
      for (const queryOption of uniqueQueryOptionsByKeys) {
        const queryKeyProps = buildKeyShapedProps({
          props,
          body,
          mutator,
          widenNonPath: makeOptionalParam,
        });

        const routeString = adapter.getQueryKeyRouteString(
          route,
          !!override.query.shouldSplitQueryKey,
        );

        // Use operation ID as query key if enabled, otherwise use route string
        const queryKeyIdentifier = override.query.useOperationIdAsQueryKey
          ? `"${operationName}"`
          : routeString;

        // Use all params in query key when useOperationIdAsQueryKey=true, otherwise use only query param
        // All params sorted by required first
        const queryKeyParams = props
          .filter((p) =>
            override.query.useOperationIdAsQueryKey
              ? true
              : p.type === GetterPropType.QUERY_PARAM,
          )
          .toSorted((a) => (a.required ? -1 : 1))
          .map((p) => `...(${p.name} ? [${p.name}] : [])`)
          .join(', ');

        const verbPrefix = getQueryKeyVerbPrefix({
          verb,
          useOperationIdAsQueryKey: override.query.useOperationIdAsQueryKey,
        });

        // Note: do not unref() params in Vue - this will make key lose reactivity
        queryKeyFns += `
${override.query.shouldExportKeys ? 'export ' : ''}const ${queryOption.queryKeyFnName} = (${queryKeyProps}) => {
    return [
    ${[
      queryOption.type === QueryType.INFINITE ||
      queryOption.type === QueryType.SUSPENSE_INFINITE
        ? `'infinite'`
        : '',
      verbPrefix ? `'${verbPrefix}'` : '',
      queryKeyIdentifier,
      queryKeyParams,
      body.implementation,
    ]
      .filter((x) => !!x)
      .join(', ')}
    ]${override.query.shouldFilterQueryKey ? `.filter(${override.query.queryKeyFilter ?? 'q => q !== undefined'})` : ' as const'};
    }
`;
      }
    } else if (override.query.shouldExportKeys) {
      // The factories call the mutator the same way the invalidate / set /
      // get helpers do (`{ url }` second arg). Query options keep their own
      // inline call — its second arg also carries `queryOptions` — so the
      // factories are only worth emitting when they are exported. Headers
      // stay in the signature: the mutator receives them inline and may key
      // on them, so dropping them would miss the hook's cache entry.
      for (const queryOption of uniqueQueryOptionsByKeys) {
        const queryKeyProps = buildKeyShapedProps({
          props,
          body,
          mutator,
          widenNonPath: makeOptionalParam,
          includeHeaders: true,
        });

        queryKeyFns += `
export const ${queryOption.queryKeyFnName} = (${queryKeyProps}) =>
    ${queryKeyMutator.name}({ ${queryProperties} }${
      queryKeyMutator.hasSecondArg ? `, { url: \`${route}\` }` : ''
    });
`;
      }
    }

    implementation += `
${queryKeyFns}`;

    let queryImplementations = '';

    for (const queryOption of queries) {
      queryImplementations += generateQueryImplementation({
        queryOption,
        operationId,
        operationName,
        typeName,
        queryProperties,
        queryKeyProperties,
        params,
        props,
        body,
        mutator,
        isRequestOptions,
        queryParams,
        response,
        httpClient,
        isExactOptionalPropertyTypes,
        hasSignal: getHasSignal({
          overrideQuerySignal: override.query.signal,
        }),
        useRuntimeFetcher: override.fetch.useRuntimeFetcher,
        forceSuccessResponse: override.fetch.forceSuccessResponse,
        includeHttpErrorResponse: override.fetch.includeHttpErrorResponse,
        queryOptionsMutator,
        queryKeyMutator,
        route,
        doc,
        deprecated,
        usePrefetch: query.usePrefetch,
        useQuery: effectiveUseQuery,
        useInfinite: effectiveUseInfinite,
        useInvalidate: query.useInvalidate,
        useSetQueryData:
          operationQueryOptions?.useSetQueryData ?? query.useSetQueryData,
        useGetQueryData:
          operationQueryOptions?.useGetQueryData ?? query.useGetQueryData,
        useSkipToken,
        adapter,
      });
    }

    implementation += `
    ${queryImplementations}
`;

    mutators =
      queryOptionsMutator || queryKeyMutator
        ? [
            ...(queryOptionsMutator ? [queryOptionsMutator] : []),
            ...(queryKeyMutator ? [queryKeyMutator] : []),
          ]
        : undefined;
  }

  let imports: GeneratorImport[] = [];

  if (isMutation) {
    const mutationResult = await generateMutationHook({
      verbOptions: { ...verbOptions, props },
      options,
      isRequestOptions,
      httpClient,
      doc,
      adapter,
    });

    implementation += mutationResult.implementation;
    mutators = mutationResult.mutators
      ? [...(mutators ?? []), ...mutationResult.mutators]
      : mutators;
    imports = mutationResult.imports;
  }

  return {
    implementation,
    mutators,
    imports,
  };
};
